sql_query:
SELECT "Control regimen"
FROM clinical_trials
WHERE "Control arm" = 'Chemo' AND "Included in MA" = 'Yes' AND "Name of ICI" = 'Pembrolizumab' AND "Trial phase" = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials WHERE "Control arm" = 'Chemo' AND "Included in MA" = 'Yes' AND "Name of ICI" = 'Pembrolizumab' AND "Trial phase" = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_specific_regimens(source_value) AS "specific_regimens"
FROM base;
